\n.md-table-bleed {\n container-type: i:
.Md-表-出血{

容器类型：内联尺寸；

--Md-table-bleed-inset：0px；

--Md-table-bleed-skew：0px；

}

.Md-表-出血-插入{

--Md-table-bleed-inset：0.5rem；

}

.Md-table-bleed .md-table-host[data-width-mode='column'] {

寬度：適合內容；

最小宽度：100%；

最大宽度：calc(100cqw - 2 * (var(--md-table-bleed-inset) + var(--md-table-bleed-skew)) - var(--md-table-bleed-end-reserve, 0px));

左边距：50%；

变换：翻译X(min(-50%, calc(50cqw - var(--md-table-bleed-end-reserve, 0px) - 100%)));

}

.Md-table-bleed .md-table-host[data-width-mode='full'] {

宽度：calc（100cqw - var（--md-table-bleed-inset）- var（--md-table-bleed-end-reserve，0px））；

Margin-inline-start: calc((100% - 100cqw) / 2 + var(--md-table-bleed-inset) + var(--md-table-bleed-skew));

}

.Md-table-bleed .bleed-contain .md-table-host[数据宽度模式] {

宽度：自动；

最小宽度：0；

最大宽度：100%；

左边距：0；

Margin-inline-start：0；

变换：无；

}

.Md-table-bleed .md-sticky-message-bleed::之前{

内容：''；

位置：绝对；

顶部：0；

底部：0；

左边：50%；

变换：翻译X（-50%）；

宽度：100cqw；

背景：var（--背景）；

Z指数：-10；

指针事件：无；

}

.Md-table-bleed .md-sticky-message-bleed::after {

左边：50%；

右：自动；

变换：翻译X（-50%）；

宽度：100cqw；

}

